function getStudyRecommendation(subjects,sessions,now){
 const valid=sessions.filter(session=>session.subject_id&&Number(session.duration_seconds)>0&&Number.isFinite(new Date(session.ended_at).getTime()));
 if(!subjects.length||!valid.length)return 'Once you log a subject-linked session, your study buddy can suggest what to revisit. For now, choose a subject and start a short focus session.';
 const lastBySubject=new Map();
 for(const session of valid){const time=new Date(session.ended_at).getTime();if(!lastBySubject.has(session.subject_id)||time>lastBySubject.get(session.subject_id))lastBySubject.set(session.subject_id,time)}
 const active=subjects.filter(subject=>!subject.total||subject.done<subject.total);
 const candidates=[...(active.length?active:subjects)];
 candidates.sort((a,b)=>(lastBySubject.get(a.id)??-Infinity)-(lastBySubject.get(b.id)??-Infinity));
 const subject=candidates[0],last=lastBySubject.get(subject.id);
 if(last===undefined)return `You haven’t logged a study session for ${subject.name} yet. A 25-minute session could help you get started.`;
 const end=new Date(last),todayKey=Date.UTC(now.getFullYear(),now.getMonth(),now.getDate()),lastKey=Date.UTC(end.getFullYear(),end.getMonth(),end.getDate()),days=Math.max(0,Math.floor((todayKey-lastKey)/86_400_000));
 if(days>=3)return `Your last logged session for ${subject.name} was ${days} days ago. A 25-minute review may help keep it familiar.`;
 return `You’ve studied ${subject.name} recently. A 25-minute session could keep your progress moving.`;
}
